{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is positive (0.00–0.67) and model overestimates prices, especially after recent spikes.",
    "Reduce forecast magnitude by 5–10% if model shows overshoot following a price spike (e.g., >70.00) and sentiment is neutral or positive.",
    "Apply mean reversion bias: if 3–5 consecutive forecast days are above 70.00, reduce forecast by 2–5% for next period unless sentiment strongly bullish.",
    "If sentiment is negative (e.g., -0.25 or below), increase forecast downward by 3–7% to reflect bearish sentiment.",
    "Avoid overfitting to recent history: if last 3–5 days show strong upward momentum, reduce forecast slope to prevent lagged overreaction.",
    "For horizon >15 days, apply smoothing: reduce forecast volatility by 10–15% if sentiment is weak or neutral, to avoid overreaction to short-term noise."
  ]
}
